#if UNITY_EDITOR
using System;using System.Collections;using System.IO;using System.Linq;using System.Text.RegularExpressions;using NUnit.Framework;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace HorrorGame.Tests{
 static class LoadingTransitionProof{
  public static IEnumerator Until(Func<bool> condition,string label,float seconds=75){double end=Time.realtimeSinceStartupAsDouble+seconds;while(!condition()&&Time.realtimeSinceStartupAsDouble<end)yield return null;Assert.That(condition(),Is.True,label);}
  public static IEnumerator SceneReady(string name){var rt=new RenderTexture(320,180,24,RenderTextureFormat.DefaultHDR);rt.Create();bool drew=false;double end=Time.realtimeSinceStartupAsDouble+90;
   try{while(Time.realtimeSinceStartupAsDouble<end){var game=GameSession.Instance;bool target=SceneManager.GetActiveScene().name==name;bool ready=name=="MainMenu"?target:target&&game&&game.narrative&&game.narrative.IsInitialized&&!game.IsRestoringCheckpoint;if(ready&&!drew){var camera=name=="MainMenu"?Camera.main:game.player.view.playerCamera;if(camera){RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt,isPreview=false});drew=true;}}if(ready&&!SceneTransitionService.ControlsBlocked)break;yield return null;}Assert.That(SceneManager.GetActiveScene().name,Is.EqualTo(name));Assert.That(SceneTransitionService.ControlsBlocked,Is.False,"Ready image must release the loading gate.");Assert.That(drew,Is.True,"Actual target camera was rendered.");}
   finally{rt.Release();UnityEngine.Object.Destroy(rt);}
  }
 }
 public sealed partial class BeforeDemolitionOfficeSceneTests{
  [UnityTest,Category("LoadingTransition")]public IEnumerator AsyncWritesSerializeAndResumeUsesValidatedMemoryInsteadOfDisk(){
   yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Initial async save completed");game.Pause();game.player.RestoreStamina(2);var first=game.save.SaveAsync();game.player.RestoreStamina(3);Assert.That(game.save.Save(),Is.True);Assert.That(SaveSystem.TryReadCheckpoint(game.save.SavePath,out var immediate,"Chapter1Office",BeforeDemolitionCampaign.StoryId),Is.True);Assert.That(immediate.stamina,Is.EqualTo(3).Within(.01f),"The existing synchronous Save contract remains intact even with an older async write.");yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Serialized writes completed");Assert.That(first.IsCompleted,Is.True);Assert.That(first.Result,Is.True);Assert.That(SaveSystem.TryReadCheckpoint(game.save.SavePath,out var saved,"Chapter1Office",BeforeDemolitionCampaign.StoryId),Is.True);Assert.That(saved.stamina,Is.EqualTo(3).Within(.01f));Assert.That(SaveSystem.StageResume(saved,game.save.SavePath),Is.True);Assert.That(SaveSystem.TestSaveDirectory,Is.Not.Null);Assert.That(Path.GetDirectoryName(game.save.SavePath),Is.EqualTo(SaveSystem.TestSaveDirectory).IgnoreCase);File.Delete(game.save.SavePath);File.Delete(game.save.SavePath+".bak");game.player.RestoreStamina(1);Assert.That(game.save.LoadCurrent(),Is.True,"The validated snapshot survives a file disappearing during Continue.");Assert.That(game.player.Stamina,Is.EqualTo(3).Within(.01f));
  }
  [UnityTest,Category("LoadingTransition"),Timeout(120000)]public IEnumerator FailedAsyncSaveCannotBlockOfficeRoadCarryAndRetryWritesArrival(){
   yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Initial checkpoint completed");LoadingSeedProof.Validate(game,false);string path=game.save.SavePath;using(var blocked=new FileStream(path+".tmp",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
    LogAssert.Expect(LogType.Warning,new Regex("Checkpoint could not be saved:"));LogAssert.Expect(LogType.Warning,new Regex("Checkpoint could not be saved:"));var failed=game.save.SaveAsync();Assert.That(game.LoadStoryChapter("RoadJourney"),Is.True);yield return LoadingTransitionProof.SceneReady("RoadJourney");yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Failed save tasks finish without retrying every frame");Assert.That(failed.IsCompleted,Is.True);Assert.That(failed.Result,Is.False);var destination=GameSession.Instance;Assert.That(destination.narrative.Progress.chapterId,Is.EqualTo(BeforeDemolitionCampaign.RoadChapterId));Assert.That(destination.interaction.inventory.Contains(BeforeDemolitionCampaign.WhistleItemId),Is.True);Assert.That(destination.save.HasPendingSave,Is.True);Assert.That(destination.CanControl,Is.True);
   }Assert.That(GameSession.Instance.save.RetryPendingSave(),Is.True);Assert.That(SaveSystem.TryReadCheckpoint(path,out var arrival,"RoadJourney",BeforeDemolitionCampaign.StoryId),Is.True);Assert.That(arrival.narrative.chapterId,Is.EqualTo(BeforeDemolitionCampaign.RoadChapterId));
  }
 }
 public sealed partial class BeforeDemolitionSchoolSceneTests{
  [UnityTest,Category("LoadingTransition"),Timeout(120000)]public IEnumerator PreloadHoldsActivationDeduplicatesAndDrainsDifferentDestinationSafely(){
   yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Initial checkpoint complete");var source=game;int before=SceneTransitionService.NativeLoadCount;Assert.That(SceneTransitionService.Preload("RoadJourney"),Is.True);Assert.That(SceneTransitionService.Preload("RoadJourney"),Is.True);Assert.That(SceneTransitionService.Preload("Chapter1Office"),Is.False);yield return LoadingTransitionProof.Until(()=>SceneTransitionService.IsPreloaded("RoadJourney"),"Preload reaches 90% without activating");Assert.That(SceneManager.GetActiveScene().name,Is.EqualTo("SchoolCEEP"));Assert.That(GameSession.Instance,Is.SameAs(source));Assert.That(SceneTransitionService.NativeLoadCount,Is.EqualTo(before+1));Assert.That(SceneTransitionService.Load("MainMenu"),Is.True);Assert.That(SceneTransitionService.Load("MainMenu"),Is.False);Assert.That(source.CanControl,Is.False);yield return LoadingTransitionProof.SceneReady("MainMenu");Assert.That(GameSession.Instance,Is.Null,"The discarded road never starts its story or writes a checkpoint.");Assert.That(SceneTransitionService.NativeLoadCount,Is.EqualTo(before+2));Assert.That(SceneTransitionService.PendingScene,Is.Null);
  }
  [UnityTest,Category("LoadingTransition"),Timeout(120000)]public IEnumerator IncompletePreloadUsesWaitingPathWithoutStartingAnotherNativeLoad(){
   int before=SceneTransitionService.NativeLoadCount;Assert.That(SceneTransitionService.Preload("MainMenu"),Is.True);Assert.That(SceneTransitionService.IsPreloaded("MainMenu"),Is.False);Assert.That(SceneTransitionService.Load("MainMenu"),Is.True);yield return LoadingTransitionProof.SceneReady("MainMenu");Assert.That(SceneTransitionService.NativeLoadCount,Is.EqualTo(before+1));
  }
  [UnityTest,Category("LoadingTransition"),Timeout(120000)]public IEnumerator RejectedTargetStartupReturnsToMenuInsteadOfWaitingForever(){
   yield return LoadingTransitionProof.Until(()=>!SaveSystem.HasQueuedWrites,"Initial checkpoint complete");Assert.That(SceneTransitionService.Load("RoadJourney"),Is.True);yield return LoadingTransitionProof.SceneReady("MainMenu");Assert.That(GameSession.Instance,Is.Null);Assert.That(SceneTransitionService.PendingScene,Is.Null);
  }
  [UnityTest,Category("LoadingTransition"),Timeout(120000)]public IEnumerator InvalidPreloadFallsBackToNormalMenuLoadWithoutLosingControl(){
   int before=SceneTransitionService.NativeLoadCount;Assert.That(SceneTransitionService.Preload("missing-loading-test-scene"),Is.False);Assert.That(SceneTransitionService.NativeLoadCount,Is.EqualTo(before));Assert.That(SceneTransitionService.Load("MainMenu"),Is.True);yield return LoadingTransitionProof.SceneReady("MainMenu");Assert.That(SceneTransitionService.NativeLoadCount,Is.EqualTo(before+1));
  }
 }
}
